import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_17/projects/recovery_aware_struct_prune/registry.yaml') as f:
    reg = yaml.safe_load(f)

# Broader search: any experiment (not just RASP) with accuracy near 54.43% or 55.19%
targets = [0.5443, 0.5519, 54.43, 55.19]
for eid, exp in reg.items():
    if exp is None: continue
    m = exp.get('metrics')
    if not m or not isinstance(m, dict): continue
    for k, v in m.items():
        try:
            fv = float(v)
            for t in targets:
                if abs(fv - t) < 0.5:
                    print(f'{eid}: {k}={fv}')
        except:
            pass
